import type { SessionSummary } from "@kurasu/contract/sessions";
import { useState } from "react";

import { Icon } from "../../ui/Icon.tsx";
import { DragHandle } from "./DragHandle.tsx";
import { EnabledLabel } from "./EnabledLabel.tsx";
import { moveTo } from "./move-to.ts";
import { NewSessionCard } from "./NewSessionCard.tsx";
import { OpenSessionLink } from "./OpenSessionLink.tsx";
import { railLook } from "./rail-look.ts";
import { RailNode } from "./RailNode.tsx";
import { SessionCard } from "./SessionCard.tsx";
import { SessionRail } from "./SessionRail.tsx";
import { useReorderSessions } from "./useReorderSessions.ts";

interface Props {
  sessions: ReadonlyArray<SessionSummary>;
  featuredPosition: number | undefined;
}

// Every session of the course, in order, dragged to reorder. The open card
// starts on the featured one.
export const AdminSessionRail = ({ sessions, featuredPosition }: Props) => {
  const [openId, setOpenId] = useState<string | null>(
    sessions.find((session) => session.position === featuredPosition)?.id ?? null,
  );

  const [dragged, setDragged] = useState<string | null>(null);
  const [over, setOver] = useState<string | null>(null);

  const reorder = useReorderSessions();

  return (
    <SessionRail
      sessions={sessions}
      openId={openId}
      onOpen={setOpenId}
      renderNode={(session) => {
        const look = session.enabled === true ? railLook(session, featuredPosition) : "locked";

        return (
          <RailNode look={look}>
            {look === "done" ? <Icon name="check" size={20} /> : null}
            {look === "live" ? (
              <Icon name="star" size={26} className="fill-current max-[600px]:size-5" />
            ) : null}
          </RailNode>
        );
      }}
      renderCard={(session, state) => (
        <div
          draggable
          onDragStart={() => setDragged(session.id)}
          onDragOver={(event) => {
            event.preventDefault();
            setOver(session.id);
          }}
          onDragEnd={() => {
            setDragged(null);
            setOver(null);
          }}
          onDrop={(event) => {
            event.preventDefault();

            if (dragged != null && dragged !== session.id) {
              reorder.mutate(
                moveTo(
                  sessions.map((each) => each.id),
                  dragged,
                  session.id,
                ),
              );
            }

            setDragged(null);
            setOver(null);
          }}
          className={`${dragged === session.id ? "opacity-40" : ""} ${
            over === session.id && dragged !== session.id
              ? "rounded-[22px] shadow-[0_-4px_0_#1f1b18]"
              : ""
          }`}
        >
          <SessionCard
            session={session}
            open={state.open}
            onToggle={state.onToggle}
            painted={session.enabled === true}
            handle={<DragHandle />}
            status={<EnabledLabel enabled={session.enabled === true} />}
            body={
              <p className="mt-3 leading-[1.45]">
                {session.summary === "" ? "Sin resumen todavía." : session.summary}
              </p>
            }
            actions={<OpenSessionLink sessionId={session.id} title={session.title} />}
          />
        </div>
      )}
      trailing={<NewSessionCard onCreated={setOpenId} />}
    />
  );
};
import type { SessionSummary } from "@kurasu/contract/sessions";
import { useEffect, useRef, useState } from "react";

import { Icon } from "../../ui/Icon.tsx";
import { EnterClassroomButton } from "./EnterClassroomButton.tsx";
import { railLook } from "./rail-look.ts";
import { RailNode } from "./RailNode.tsx";
import { SessionCard } from "./SessionCard.tsx";
import { SessionLinks } from "./SessionLinks.tsx";
import { SessionRail } from "./SessionRail.tsx";

interface Props {
  sessions: ReadonlyArray<SessionSummary>;
  featuredPosition?: number | undefined;
  initialOpenId?: string | undefined;
}

// A link to one of the sessions, such as the one of an announcement mail, opens
// its card and brings it to the middle of the screen. An id that is not among
// them opens nothing.
export const AllSessions = ({ sessions, featuredPosition, initialOpenId }: Props) => {
  const [openId, setOpenId] = useState<string | null>(initialOpenId ?? null);

  const linkedCard = useRef<HTMLElement>(null);

  useEffect(() => {
    linkedCard.current?.scrollIntoView({ block: "center" });
  }, []);

  return (
    <SessionRail
      sessions={sessions}
      openId={openId}
      onOpen={setOpenId}
      renderNode={(session) => {
        const look = railLook(session, featuredPosition);

        return (
          <RailNode look={look}>
            {look === "done" ? <Icon name="check" size={20} /> : null}
            {look === "live" ? (
              <Icon name="star" size={26} className="fill-current max-[600px]:size-5" />
            ) : null}
          </RailNode>
        );
      }}
      renderCard={(session, state) => (
        <SessionCard
          ref={session.id === initialOpenId ? linkedCard : undefined}
          session={session}
          open={state.open}
          onToggle={state.onToggle}
          body={
            <div>
              <SessionLinks sessionId={session.id} featured={session.featured} />
              <p className="mt-3 leading-[1.45]">{session.summary}</p>
              {session.featured ? <EnterClassroomButton /> : null}
            </div>
          }
        />
      )}
    />
  );
};
import type { ReactNode } from "react";

interface Props {
  look: "done" | "live" | "later" | "locked" | "new";
  children: ReactNode;
}

const looks = {
  done: "bg-active text-active-ink",
  live: "bg-live text-white shadow-[0_0_0_6px_color-mix(in_srgb,#e8505b_25%,transparent)] max-[600px]:shadow-[0_0_0_4px_color-mix(in_srgb,#e8505b_25%,transparent)]",
  later: "bg-line",
  locked: "border-2 border-dashed border-line text-muted",
  new: "border-2 border-dashed border-line text-muted",
};

export const RailNode = ({ look, children }: Props) => (
  <div
    className={`skeleton-block grid size-11 flex-none place-items-center rounded-full font-display font-bold max-[600px]:size-8 max-[600px]:text-sm ${looks[look]}`}
  >
    {children}
  </div>
);
import type { SessionSummary } from "@kurasu/contract/sessions";

// Before the featured session the node is done, on it live, after it, or with
// no featured session, later.
export const railLook = (
  session: Pick<SessionSummary, "position">,
  featuredPosition: number | undefined,
) => {
  if (featuredPosition == null || session.position > featuredPosition) {
    return "later";
  }

  return session.position === featuredPosition ? "live" : "done";
};
import type { Session, SessionSummary } from "@kurasu/contract/sessions";

import { ConfirmAction } from "../../ui/ConfirmAction.tsx";
import { Switch } from "../../ui/Switch.tsx";
import { FeaturedEffects } from "./FeaturedEffects.tsx";
import { useUpdateSession } from "./useUpdateSession.ts";

interface Props {
  session: Session;
  featured: SessionSummary | undefined;
}

const errorText = "No se pudo guardar el cambio. Probá de nuevo.";

// Featuring a session when another one is featured, and removing the mark,
// ask first because the session that stops being featured loses its active
// polls, its raised hands and its featured questions.
export const FeaturedSwitch = ({ session, featured }: Props) => {
  const update = useUpdateSession();

  const toggle = (onClick: () => void, isPending = false) => (
    <button
      type="button"
      role="switch"
      aria-checked={session.featured}
      disabled={session.enabled !== true || isPending}
      onClick={onClick}
      className="mt-3 flex items-center gap-2.5 text-sm"
    >
      <span>Destacada</span>
      <Switch on={session.featured} />
    </button>
  );

  return (
    <>
      {session.featured ? (
        <ConfirmAction
          renderTrigger={(ask) => toggle(ask)}
          title={`¿Sacarle la marca de destacada a "${session.title}"?`}
          text="La sesión deja de ser la destacada y nadie entra a ningún aula hasta que destaques otra."
          content={<FeaturedEffects session={session} />}
          confirmIcon={null}
          confirmLabel="Sacar la marca"
          pendingLabel="Sacando la marca…"
          errorText={errorText}
          onConfirm={() => update.mutateAsync({ id: session.id, change: { featured: false } })}
        />
      ) : null}
      {!session.featured && featured != null ? (
        <ConfirmAction
          renderTrigger={(ask) => toggle(ask)}
          title={`¿Destacar "${session.title}"?`}
          text={`"${featured.title}" deja de ser la destacada:`}
          content={<FeaturedEffects session={featured} />}
          confirmIcon={null}
          confirmLabel="Destacar"
          pendingLabel="Destacando…"
          errorText={errorText}
          onConfirm={() => update.mutateAsync({ id: session.id, change: { featured: true } })}
        />
      ) : null}
      {!session.featured && featured == null
        ? toggle(
            () => update.mutate({ id: session.id, change: { featured: true } }),
            update.isPending,
          )
        : null}
      {session.enabled === true ? null : (
        <div className="mt-1.5 text-[13px] opacity-75">
          Habilitá la sesión para poder destacarla.
        </div>
      )}
    </>
  );
};
import type { Session, SessionSummary } from "@kurasu/contract/sessions";
import { useState } from "react";

import { ConfirmAction } from "../../ui/ConfirmAction.tsx";
import { Switch } from "../../ui/Switch.tsx";
import { EnableSessionDialog } from "./EnableSessionDialog.tsx";
import { FeaturedEffects } from "./FeaturedEffects.tsx";
import { useUpdateSession } from "./useUpdateSession.ts";

interface Props {
  session: Session;
  featured: SessionSummary | undefined;
}

// Enabling opens a dialog that can also feature the session; disabling the
// featured session asks first; disabling any other session is immediate.
export const EnabledSwitch = ({ session, featured }: Props) => {
  const [isEnabling, setIsEnabling] = useState(false);

  const update = useUpdateSession();

  const enabled = session.enabled === true;

  const toggle = (onClick: () => void) => (
    <button
      type="button"
      role="switch"
      aria-checked={enabled}
      disabled={update.isPending}
      onClick={onClick}
      className="mt-4 flex items-center gap-2.5 text-sm"
    >
      <span>{enabled ? "Habilitada" : "Deshabilitada"}</span>
      <Switch on={enabled} />
    </button>
  );

  if (!enabled) {
    return (
      <>
        {toggle(() => setIsEnabling(true))}
        {isEnabling ? (
          <EnableSessionDialog
            session={session}
            featured={featured}
            onClose={() => setIsEnabling(false)}
          />
        ) : null}
      </>
    );
  }

  return session.featured ? (
    <ConfirmAction
      renderTrigger={(ask) => toggle(ask)}
      title={`¿Deshabilitar "${session.title}"?`}
      text="Es la sesión destacada: al deshabilitarla deja de serlo, y nadie entra a ningún aula hasta que destaques otra."
      content={<FeaturedEffects session={session} />}
      confirmIcon={null}
      confirmLabel="Deshabilitar"
      pendingLabel="Deshabilitando…"
      errorText="No se pudo guardar el cambio. Probá de nuevo."
      onConfirm={() => update.mutateAsync({ id: session.id, change: { enabled: false } })}
    />
  ) : (
    toggle(() => update.mutate({ id: session.id, change: { enabled: false } }))
  );
};
import type { SessionSummary } from "@kurasu/contract/sessions";

import { SkeletonOf } from "../../ui/SkeletonOf.tsx";
import { useAdminRaisedHands } from "../hands/useAdminRaisedHands.ts";
import { useAdminPolls } from "../polls/useAdminPolls.ts";

interface Props {
  session: SessionSummary;
}

const countLabel = (count: number, one: string, many: string) =>
  `${count} ${count === 1 ? one : many}`;

// What the session that stops being featured loses; its unanswered questions
// and its slide stay.
export const FeaturedEffects = ({ session }: Props) => {
  const polls = useAdminPolls(session.id);
  const hands = useAdminRaisedHands(session.id);

  const active = polls.data?.filter((poll) => poll.status === "active").length;

  return polls.data == null || hands.data == null ? (
    <SkeletonOf>
      <ul className="mt-2.5 list-disc pl-5 text-sm">
        <li className="skeleton-block">Se cierra 1 encuesta activa.</li>
        <li className="skeleton-block">Se baja 1 mano levantada.</li>
      </ul>
    </SkeletonOf>
  ) : (
    <ul className="mt-2.5 list-disc pl-5 text-sm leading-[1.45]">
      <li>
        {active === 0 || active == null
          ? "No hay encuestas activas que cerrar."
          : `${active === 1 ? "Se cierra" : "Se cierran"} ${countLabel(active, "encuesta activa", "encuestas activas")}, el feedback incluido si está abierto.`}
      </li>
      <li>
        {hands.data.length === 0
          ? "No hay manos levantadas."
          : `${hands.data.length === 1 ? "Se baja" : "Se bajan"} ${countLabel(hands.data.length, "mano levantada", "manos levantadas")}.`}
      </li>
      {session.featuredQuestions ? <li>Se apaga el modo de preguntas destacadas.</li> : null}
      <li>Las preguntas sin responder y la slide quedan como están.</li>
    </ul>
  );
};
import type { SessionSummary } from "@kurasu/contract/sessions";

import type { EndpointError, QueryOptions } from "../../api/api-error.ts";
import { useAdminSessions } from "./useAdminSessions.ts";

const findFeatured = (sessions: ReadonlyArray<SessionSummary>) =>
  sessions.find((session) => session.featured);

// The featured session of the admin's list, or undefined while there is none.
export const useFeaturedSession = (
  options?: Omit<
    QueryOptions<
      ReadonlyArray<SessionSummary>,
      EndpointError<"adminSessions", "list">,
      SessionSummary | undefined
    >,
    "select"
  >,
) => useAdminSessions({ ...options, select: findFeatured });

import * as Context from "effect/Context";
import type * as Effect from "effect/Effect";

// A write that has not run yet. The core only passes it to `Batch.run`; the
// adapter that builds it is the one that knows how to run it.
export interface Write {
  readonly toSQL: () => { readonly sql: string; readonly params: ReadonlyArray<unknown> };
}

// Runs writes of several stores as one atomic batch, in order. A failure is a
// defect and none of the writes applies.
export class Batch extends Context.Service<
  Batch,
  { readonly run: (writes: ReadonlyArray<Write>) => Effect.Effect<void> }
>()("kurasu/Batch") {}
import { Batch } from "@kurasu/core/batch";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";

import { batch, Database } from "./database.ts";

export const D1Batch = Layer.effect(
  Batch,
  Effect.gen(function* () {
    const { client } = yield* Database;

    return Batch.of({ run: (writes) => batch(client, writes) });
  }),
);
